    .header { border-bottom: 1px solid var(--line); }
    .nav { min-height: 88px; display: flex; align-items: center; gap: var(--space-12); }
    .logo { display: inline-flex; align-items: center; gap: var(--space-3); font: 28px/1 var(--serif); letter-spacing: -.04em; }
    .logo svg { width: 25px; height: 30px; color: var(--accent); flex: none; }
    .nav-links, .nav-actions { display: flex; align-items: center; gap: var(--space-8); }
    .nav-links { margin-left: var(--space-4); }
    .nav-actions { margin-left: auto; gap: var(--space-6); }
    .nav-link { min-height: 44px; display: inline-flex; align-items: center; color: var(--muted); }
    .nav-link:hover { color: var(--accent); }
    .nav-link[aria-current] { color: var(--ink); text-decoration: underline; text-underline-offset: 8px; text-decoration-color: var(--accent); }
    .button { display: inline-flex; min-height: 48px; justify-content: center; align-items: center; gap: var(--space-3); padding: var(--space-3) var(--space-6); border: 1px solid var(--control-border); border-radius: var(--radius); background: transparent; color: var(--ink); font-weight: 500; line-height: 1.4; transition: background 150ms, border-color 150ms, color 150ms; }
    .button:hover { background: var(--accent-soft); border-color: var(--accent); }
    .button:active { background: var(--line); }
    .button-primary { background: var(--accent); color: var(--surface); border-color: var(--accent); }
    .button-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
    .button-primary:active { background: var(--accent); }
    .nav-actions .button { min-height: 44px; padding: var(--space-2) var(--space-4); }
    .hero { text-align: center; padding: var(--space-16) 0 var(--space-12); }
    h1, h2, h3, p { margin: 0; }
    h1 { font: 400 clamp(40px, 5vw, 64px)/1.1 var(--serif); letter-spacing: -.045em; text-wrap: balance; }
    .hero p { margin: var(--space-6) auto var(--space-8); max-width: 48ch; color: var(--muted); font-size: var(--text-large); }
    .billing { display: inline-flex; gap: var(--space-1); padding: var(--space-1); border: 1px solid var(--control-border); border-radius: 6px; }
    .billing button { min-height: 44px; border: 0; border-radius: var(--radius); padding: var(--space-2) var(--space-4); background: transparent; color: var(--muted); font-size: var(--text-body); }
    .billing button:hover { color: var(--ink); background: var(--accent-soft); }
    .billing button[aria-pressed=\"true\"] { background: var(--ink); color: var(--surface); }
    .saving { margin-left: var(--space-2); color: var(--accent); font-size: var(--text-small); }
    [aria-pressed=\"true\"] .saving { color: var(--surface); }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); }
    .plan { position: relative; display: flex; flex-direction: column; padding: var(--space-8); border: 1px solid var(--line); border-radius: var(--radius); background: var(--surface); }
    .plan.popular { border-color: var(--accent); background: var(--accent-soft); }
    .popular::before { content: ''; position: absolute; top: -1px; left: -1px; right: -1px; height: 4px; border-radius: var(--radius) var(--radius) 0 0; background: var(--accent); }
    .plan-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); }
    .plan h2 { font: 400 32px/1.2 var(--serif); letter-spacing: -.03em; }
    .badge { color: var(--accent); font-size: var(--text-small); font-weight: 500; }
    .desc { color: var(--muted); margin-top: var(--space-2); font-size: var(--text-body); }
    .price { display: flex; align-items: baseline; gap: var(--space-2); margin-top: var(--space-6); font-variant-numeric: tabular-nums; }
    .amount { font-size: 48px; letter-spacing: -.06em; font-weight: 500; line-height: 1.2; }
    .period { color: var(--muted); font-size: var(--text-small); }
    .billing-note { color: var(--muted); font-size: var(--text-small); min-height: 24px; margin: var(--space-2) 0 var(--space-6); }
    .plan .button { width: 100%; justify-content: space-between; }
    .arrow { font-size: var(--text-large); font-weight: 400; }
    .plan ul { list-style: none; padding: var(--space-6) 0 0; margin: var(--space-6) 0 0; border-top: 1px solid var(--line); display: grid; gap: var(--space-3); }
    .popular ul { border-color: #d4bdb3; }
    .plan li { display: flex; align-items: baseline; gap: var(--space-3); font-size: var(--text-body); }
    .plan li::before { content: ''; flex: none; display: block; width: 12px; height: 7px; border-left: 1.5px solid var(--accent); border-bottom: 1.5px solid var(--accent); transform: rotate(-45deg) translateY(-3px); }
    .plan li.unavailable { color: var(--muted); }
    .plan li.unavailable::before { height: 1px; border: 0; background: var(--muted); transform: translateY(-4px); }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
    .features { padding: var(--space-16) 0; }
    .section-heading { font: 400 36px/1.2 var(--serif); letter-spacing: -.035em; text-wrap: balance; }
    .features > h2 { margin-bottom: var(--space-8); }
    .feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-12); }
    .feature-title { display: flex; align-items: center; gap: var(--space-3); }
    .feature-title svg { width: 20px; height: 20px; flex: none; color: var(--accent); fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
    .feature h3 { font-size: var(--text-body); font-weight: 500; }
    .feature p { margin-top: var(--space-2); color: var(--muted); max-width: 32ch; }
    .faq { display: grid; grid-template-columns: 1fr 2fr; gap: var(--space-16); border-top: 1px solid var(--line); padding: var(--space-16) 0 var(--space-24); }
    .faq h2 { max-width: 12ch; }
    .q { border-bottom: 1px solid var(--line); }
    .q:first-child { border-top: 1px solid var(--line); }
    .q summary { cursor: pointer; list-style: none; display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); min-height: 64px; padding: var(--space-4) 0; font-weight: 500; }
    .q summary::-webkit-details-marker { display: none; }
    .q summary::after { content: '+'; color: var(--accent); font-size: 24px; font-weight: 400; }
    .q[open] summary::after { content: '−'; }
    .q summary:hover { color: var(--accent); }
    .q p { color: var(--muted); padding: 0 var(--space-8) var(--space-6) 0; max-width: 65ch; }
    .footer { border-top: 1px solid var(--line); }
    .footer-inner { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding-block: var(--space-8); }
    .footer .logo { font-size: 24px; }
    .footer p { color: var(--muted); font-size: var(--text-small); }
    @media (max-width: 1000px) {
      .container { width: calc(100% - 64px); }
      .nav { gap: var(--space-6); }
      .nav-links { margin-left: 0; gap: var(--space-6); }
      .plans { gap: var(--space-4); }
      .plan { padding: var(--space-6); }
      .plan-heading { align-items: flex-start; flex-direction: column; gap: var(--space-1); min-height: 64px; }
      .desc { min-height: 48px; }
      .price { flex-wrap: wrap; gap: var(--space-1); }
      .period { white-space: nowrap; }
      .feature-grid { gap: var(--space-6); }
      .faq { gap: var(--space-8); }
    }
    @media (max-width: 700px) {
      .container { width: calc(100% - 40px); }
      .nav { min-height: 80px; flex-wrap: wrap; gap: 0; padding-top: var(--space-4); }
      .logo { font-size: 26px; }
      .nav-actions { gap: var(--space-4); }
      .nav-actions > .nav-link { display: none; }
      .nav-links { order: 3; width: 100%; justify-content: center; gap: var(--space-8); padding-top: var(--space-2); }
      .hero { padding: var(--space-12) 0 var(--space-8); }
      .hero p { font-size: 1rem; margin-top: var(--space-4); }
      .billing button { padding-inline: var(--space-3); }
      .saving { margin-left: var(--space-1); }
      .plans { grid-template-columns: 1fr; gap: var(--space-6); }
      .plan { padding: var(--space-8); }
      .plan-heading { min-height: auto; flex-direction: row; align-items: center; }
      .desc { min-height: auto; }
      .feature-grid { grid-template-columns: 1fr; gap: var(--space-8); }
      .feature p { max-width: 45ch; }
      .features { padding-block: var(--space-12); }
      .section-heading { font-size: 32px; }
      .faq { grid-template-columns: 1fr; gap: var(--space-8); padding-block: var(--space-12); }
      .faq h2 { max-width: none; }
      .footer-inner { flex-direction: column; align-items: flex-start; gap: var(--space-4); }
    }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none "'!important; scroll-behavior: auto !important; } }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to content</a>
  <header class="header">
    <nav class="nav container" aria-label="Main navigation">
      <a class="logo" href="#" aria-label="Marginalia home">
        <svg viewBox="0 0 25 30" fill="none" aria-hidden="true"><path d="M5 2h18v25H5z" stroke="currentColor" stroke-width="1.5"/><path d="M1 6v23h18M10 3v23M13 9h6M13 14h6M13 19h4" stroke="currentColor" stroke-width="1.2"/></svg>
        Marginalia
      </a>
      <div class="nav-links">
        <a class="nav-link" href="#features">Features</a>
        <a class="nav-link" href="#pricing" aria-current="page">Pricing</a>
        <a class="nav-link" href="#">Blog</a>
      </div>
      <div class="nav-actions">
        <a class="nav-link" href="#">Log in</a>
        <a class="button" href="#">Sign up free <span aria-hidden="true">↗</span></a>
      </div>
    </nav>
  </header>

  <main id="main" class="container">
    <section class="hero" aria-labelledby="page-title">
      <h1 id="page-title">Make room for your ideas.</h1>
      <p>From your first note to your team’s shared notebooks.<br>Choose the plan that fits.</p>
      <div class="billing" role="group" aria-label="Billing period">
        <button type="button" aria-pressed="true" data-billing="monthly">Monthly</button>
        <button type="button" aria-pressed="false" data-billing="yearly">Yearly <span class="saving">Save 20%</span></button>
      </div>
    </section>

    <section id="pricing" class="plans" aria-label="Compare pricing plans">
      <article class="plan">
        <div class="plan-heading"><h2>Starter</h2></div>
        <p class="desc">For your first notebook.</p>
        <div class="price"><span class="amount">$0</span><span class="period">/ month</span></div>
        <p class="billing-note">Free to get started.</p>
        <a class="button" href="#" aria-label="Get started with Starter">Start free <span class="arrow" aria-hidden="true">→</span></a>
        <ul>
          <li>Up to 100 notes</li>
          <li>2 devices</li>
          <li>Basic search</li>
          <li class="unavailable"><span class="sr-only">Not included: </span>Offline access</li>
          <li class="unavailable"><span class="sr-only">Not included: </span>Shared notebooks</li>
        </ul>
      </article>
      <article class="plan popular">
        <div class="plan-heading"><h2>Pro</h2><span class="badge">Most popular</span></div>
        <p class="desc">For a growing world of ideas.</p>
        <div class="price"><span class="amount" data-monthly="8">$8</span><span class="period">/ month</span></div>
        <p class="billing-note" data-billing-note="8">Billed monthly.</p>
        <a class="button button-primary" href="#" aria-label="Start your free Pro trial">Try Pro free <span class="arrow" aria-hidden="true">→</span></a>
        <ul>
          <li>Unlimited notes</li>
          <li>Unlimited devices</li>
          <li>Full-text search inside PDFs</li>
          <li>Offline access</li>
          <li class="unavailable"><span class="sr-only">Not included: </span>Shared notebooks</li>
        </ul>
      </article>
      <article class="plan">
        <div class="plan-heading"><h2>Team</h2></div>
        <p class="desc">For thinking together.</p>
        <div class="price"><span class="amount" data-monthly="14">$14</span><span class="period">/ user / month</span></div>
        <p class="billing-note" data-billing-note="14">Billed monthly.</p>
        <a class="button" href="#" aria-label="Get started with Team">Choose Team <span class="arrow" aria-hidden="true">→</span></a>
        <ul>
          <li>Everything in Pro</li>
          <li>Shared notebooks</li>
          <li>Admin controls</li>
          <li>Priority support</li>
          <li>SSO</li>
        </ul>
      </article>
    </section>
    <p id="billing-status" class="sr-only" aria-live="polite"></p>

    <section id="features" class="features" aria-labelledby="features-title">
      <h2 id="features-title" class="section-heading">Keep your thoughts close.</h2>
      <div class="feature-grid">
        <div class="feature">
          <div class="feature-title"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m13 2-9 12h7l-1 8 10-13h-7z"/></svg><h3>Fast search</h3></div>
          <p>Find the note you’re looking for, without breaking your train of thought.</p>
        </div>
        <div class="feature">
          <div class="feature-title"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg><h3>Secure by design</h3></div>
          <p>Your notes are encrypted, so your private thoughts stay private.</p>
        </div>
        <div class="feature">
          <div class="feature-title"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8a8 8 0 0 1 13-2l2 2M20 3v5h-5M19 16a8 8 0 0 1-13 2l-2-2M4 21v-5h5"/></svg><h3>In sync, everywhere</h3></div>
          <p>Your notes, ready when you are. Stay in sync across your devices.</p>
        </div>
      </div>
    </section>

    <section class="faq" aria-labelledby="faq-title">
      <h2 id="faq-title" class="section-heading">A few good<br>questions.</h2>
      <div>
        <details class="q" open>
          <summary>Can I cancel anytime?</summary>
          <p>Yes. You can cancel your subscription at any time, no questions asked.</p>
        </details>
        <details class="q">
          <summary>Is there a free trial for Pro?</summary>
          <p>Yes. Pro includes a 14-day free trial. No credit card required.</p>
        </details>
        <details class="q">
          <summary>Do you offer student discounts?</summary>
          <p>Students get 50% off Pro with a valid school email.</p>
        </details>
      </div>
    </section>
  </main>

  <footer class="footer">
    <div class="container footer-inner">
      <a class="logo" href="#">Marginalia</a>
      <p>© 2026 Marginalia Inc. All rights reserved.</p>
    </div>
  </footer>
  <script>
    const billingButtons = document.querySelectorAll('"'[data-billing]');
    const money = value => '"'$'"' + Number(value.toFixed(2)).toString();
    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const yearly = button.dataset.billing === 'yearly';
        billingButtons.forEach(option => option.setAttribute('aria-pressed', String(option === button)));
        document.querySelectorAll('[data-monthly]').forEach(price => {
          price.textContent = money(Number(price.dataset.monthly) * (yearly ? .8 : 1));
        });
        document.querySelectorAll('[data-billing-note]').forEach(note => {
          const annual = money(Number(note.dataset.billingNote) * .8 * 12);
          const perUser = note.dataset.billingNote === '14' ? ' per user' : '';
          note.textContent = yearly ? "'`${annual}${perUser}, billed yearly.` : '"'Billed monthly.';
        });
        document.getElementById('billing-status').textContent = yearly
          ? 'Yearly billing selected. Pro: "'$6.40 per month, $76.80 billed yearly. Team: $11.20 per user per month, $134.40 per user billed yearly.'"'
          : 'Monthly billing selected. Pro: "'$8 per month. Team: $14 per user per month.'"';
      });
    });
  </script>
</body>
</html>
EOF
